<?php
namespace App\Http\Controllers\Api; use App\Http\Controllers\Controller; use App\Models\Member; use Illuminate\Http\Request;
class MemberController extends Controller { public function index(){return Member::orderBy('plot_no')->paginate(50);} public function store(Request $r){$d=$r->validate(['member_code'=>'required|unique:members','plot_no'=>'required','owner_name'=>'required','mobile'=>'nullable','email'=>'nullable|email','status'=>'required','monthly_fee'=>'required|numeric']); return Member::create($d);} public function show(Member $member){return $member;} public function update(Request $r,Member $member){$member->update($r->validate(['plot_no'=>'sometimes','owner_name'=>'sometimes','mobile'=>'nullable','email'=>'nullable|email','status'=>'sometimes','monthly_fee'=>'sometimes|numeric'])); return $member;} public function destroy(Member $member){$member->delete(); return response()->noContent();} }
